type UserPreferences = Record<string, unknown>;

async function getUserPreferences(): Promise<UserPreferences> {
  try {
    const res = await fetch('https://api.example.com/user/preferences', {
      cache: 'no-store',
    });

    if (!res.ok) {
      throw new Error('Failed to fetch user preferences');
    }

    return res.json();
  } catch {
    // Keep the dashboard renderable if the API is unavailable.
    return { message: 'Preferences are currently unavailable.' };
  }
}

export default async function UserDashboard() {
  const preferences = await getUserPreferences();

  return (
    <div>
      <h2>User Dashboard</h2>
      <p>Your preferences:</p>
      <pre>{JSON.stringify(preferences, null, 2)}</pre>
    </div>
  );
}

